// Un mensaje por robot MiR para pedirle datos a la API.
// Las IPs se ven aquí; el token (secreto) viene de una variable de entorno.
const robots = [
    { id: 'mir1', host: env.get('MIR1_IP'), token: env.get('MIR1_TOKEN') },
    { id: 'mir2', host: env.get('MIR2_IP'), token: env.get('MIR2_TOKEN') }
];

// guartadamos las peticiones por robot
const salida = [];
for (const r of robots) {
    // Si falta el token, se salta ese robot
    if (!r.token) continue;   // guardamos de que robot es
    salida.push({
        topic: msg.topic,        // endpoint a pedir (status, missions...)
        robot_id: r.id,          // sirve luego como etiqueta en InfluxDB
        url: 'http://' + r.host + '/api/v2.0.0/' + msg.topic,
        headers: {
            'Authorization': 'Basic ' + r.token,
            'Accept-Language': 'en_US'
        }
    });
}
// Un mensaje por cada robot
return [salida];

// Solo procesamos las respuestas de "status"
if (msg.topic !== 'status') return null;


// s = JSON que devolvió el robot
const s = msg.payload;
if (!s || typeof s !== 'object') return null;


// Devuelve el valor si es número, si no null (InfluxDB fija el tipo del campo)
const n = (v) => (typeof v === 'number' ? v : null);


// Valores numéricos a guardar (position y velocity son objetos anidados)
const candidatos = {
    pos_x: n(s.position && s.position.x),
    pos_y: n(s.position && s.position.y),
    orientation: n(s.position && s.position.orientation),
    vel_linear: n(s.velocity && s.velocity.linear),
    vel_angular: n(s.velocity && s.velocity.angular),
    battery_percentage: n(s.battery_percentage),
    battery_time_remaining: n(s.battery_time_remaining),
    moved: n(s.moved),
    distance_to_next_target: n(s.distance_to_next_target),
    uptime: n(s.uptime),
    state_id: n(s.state_id),
    mode_id: n(s.mode_id)
};


// Campos: nos quedamos solo con los que son número
const campos = {};
for (const k in candidatos) {
    if (candidatos[k] !== null) campos[k] = candidatos[k];
}


// Otros campos: nº de errores, booleanos y texto de la misión
campos.errors_count = Array.isArray(s.errors) ? s.errors.length : 0;
campos.safety_system_muted = !!s.safety_system_muted;
campos.joystick_low_speed_mode = !!s.joystick_low_speed_mode_enabled;
campos.unloaded_map_changes = !!s.unloaded_map_changes;
campos.mission_text = String(s.mission_text || '');


// Tags: categorías con pocos valores (nunca batería ni posición)
const tags = {
    robot: String(msg.robot_id || 'desconocido'),   // mir1 o mir2
    robot_name: String(s.robot_name || 'desconocido'),
    robot_model: String(s.robot_model || 'desconocido'),
    state_text: String(s.state_text || 'desconocido'),
    mode_text: String(s.mode_text || 'desconocido'),
    mode_key_state: String(s.mode_key_state || 'desconocido')
};


// Salida para influxdb out: [campos, tags]
msg.measurement = 'mir_status';
msg.payload = [campos, tags];
return msg;

// PASO 1: de todo lo que llega de arriba, solo nos interesa la cola de órdenes.
// Si es otra cosa (status, posiciones...), no hacemos nada.
if (msg.topic !== 'mission_queue' || !Array.isArray(msg.payload)) return null;

// PASO 2: de la lista de órdenes, nos quedamos solo con las terminadas ('Done').
const terminadas = msg.payload.filter(orden => orden.state === 'Done');
if (terminadas.length === 0) return null;

// PASO 3: cada orden tiene un número (id) que va creciendo.
// Buscamos el número de la orden terminada más reciente.
const ultimaId = Math.max(...terminadas.map(orden => orden.id));

// PASO 4: el nodo tiene una pequeña memoria ('context').
// Miramos hasta qué orden revisamos la vez anterior y guardamos la de ahora.
const clave = 'revisada_' + msg.robot_id;
const revisadaAntes = context.get(clave);
context.set(clave, ultimaId);

// PASO 5: la primera vez no hay nada guardado. En ese caso revisamos
// también las últimas 30 órdenes, para tener datos desde el principio.
const desde = (revisadaAntes === undefined) ? ultimaId - 30 : revisadaAntes;

// PASO 6: las órdenes nuevas son las terminadas después de 'desde'.
const nuevas = terminadas.filter(orden => orden.id > desde);

// PASO 7: por cada orden nueva, preparamos una petición para pedir su detalle
// (con sus horas) al robot que corresponde.
const ip = { mir1: '192.168.15.5', mir2: '192.168.15.15' };
return [nuevas.map(orden => ({
    robot_id: msg.robot_id,
    url: 'http://' + ip[msg.robot_id] + '/api/v2.0.0/mission_queue/' + orden.id,
    headers: {
        'Authorization': 'Basic ' + env.get(msg.robot_id.toUpperCase() + '_TOKEN'),
        'Accept-Language': 'en_US'
    }
}))];

// PASO 1: si el robot no ha respondido bien, no hacemos nada.
if (msg.statusCode !== 200) return null;

// PASO 2: guardamos la respuesta del robot con un nombre más corto.
const orden = msg.payload;

// PASO 3: comprobamos que vienen las tres horas que necesitamos.
// Si falta alguna, avisamos en el panel de depuración con los campos que sí vienen.
if (!orden.ordered || !orden.started || !orden.finished) {
    node.warn('Faltan horas. Campos recibidos: ' + Object.keys(orden).join(', '));
    return null;
}

// PASO 4: convertimos cada hora en un número de milisegundos para poder restarlas.
const horaPedida = Date.parse(orden.ordered);   // cuando se mandó la orden
const horaInicio = Date.parse(orden.started);   // cuando el robot empezó
const horaFin    = Date.parse(orden.finished);  // cuando el robot terminó

// PASO 5: calculamos los tiempos en segundos (dividimos entre 1000).
const espera   = (horaInicio - horaPedida) / 1000;  // el delay: de mandar a empezar
const duracion = (horaFin - horaInicio) / 1000;     // lo que tardó en hacerla
const total    = (horaFin - horaPedida) / 1000;     // de mandar a terminar

// PASO 6: preparamos el dato para InfluxDB.
// Primer bloque: los valores. Segundo bloque: la etiqueta con el robot.
msg.payload = [
    {
        espera_s: espera,
        duracion_s: duracion,
        total_s: total,
        time: new Date(horaPedida)   // el dato se guarda con la hora en que se mandó la orden
    },
    { robot: msg.robot_id }
];

// PASO 7: le decimos al nodo de InfluxDB dónde guardarlo y lo enviamos.
msg.measurement = 'mir_misiones';
return msg;
